#!/bin/bash
# dsm-kvres.sh (13.11.2026, queue-ar/dsmain/kvres, a builder for ds-main-port) -- NOT a queue item; the body of
# 57-p4zyzzzzz-ds-r92zzzzzz-ref12zzzzzzzzzzzz-zsoak16zz-kvres.sh. Log tag "RESULT xkvr ", out runs/xdsm/kvres (KVR_OUT). A COPY of
# zzzc16/dsm-zzzc16.sh (md5 00cfc8b8, as staged + run 13.11.; tag xkvr -> xkvr, knobs KVR_ -> KVR_; generated by kvres/mkbodykv.py, every
# edit an asserted replacement; zzzc16's body not changed; unused functions kept): the SAME int16 start words, guards, image literal checks
# (int9 .. int14c + the fuse image's), n-gram reuse (tools/ngramshare/ngshare.sh), A4's table + A11's ranged entries (zzzc16's = ref14's,
# md5-checked, NOT re-benched), THE int16 PIN posted as O right after each start and READ BACK (rankrb + pin16 + fusestart, as zzzc16), the
# harness gens window (harness/ncmb3.py via mbx), yswl/resprobe.py 1u reads (blockx); kvres/kvsum.py = the placement read-back + the summary.
# THE KV-RESERVATION vs EXPERT-RESIDENCY TRADE-OFF on int16 (ds-main-port 13.11.; MEASUREMENT ONLY, nothing adopted):
#   THE KNOB (radiance-int14c source, read, not guessed): --host-pool-mib (lib-pr266 HOSTPOOL = the body's HP29; 19456 in every DS start).
#   core/place/planner.cpp:103 expert_vram_floor = all experts + spare slots + 2 x the largest unit - the host room; the host room =
#   --host-pool-mib (core/engine_bringup.cpp:2250-2255); core/mem/vram_budget.cpp:189-199 (the cache lends): experts get that floor, the KV
#   cache elastic - floor (never below one --max-model-len sequence), the prefill staging ring comes out of the cache (vram_budget.cpp:243-254).
#   So --host-pool-mib -X MiB = the expert slab +X MiB = the KV pool -X MiB (less the staging ring's shrink). --max-model-len 524288,
#   --max-num-seqs 16 and --gpu-headroom-mib (planner.h:167 "untouchable") stay; RADIANCE_PLACE_TURNOVER stays 0 (stackenv), draft lend on.
#   What the arms move: the KV cache LENDS every block no live request holds to the expert slab (core/engine.cpp:2141 loan_tick,
#   core/mem/kv.cpp:882 spare_tokens: above the highest held block + a buffer of one prefill chunk), so a smaller KV pool turns KV-LENT slots
#   into OWNED slab slots; the VRAM-resident total changes only where KV is held (zzzfuse c8 F window: KV-lent held 739-743 of 748 lendable a rank).
# ARMS (one fresh start each, KVR_ARMS "ARM:HOSTPOOL_MIB ..."): K35 16800 (KV pool ~-35 %: 6.95 -> ~4.50 GiB a card) and K60 14900 (~-60 %:
#   ~2.75 GiB). K0 = 19456 is NOT re-run (TESTING.md 2.): its placement = zzzc16's start log, its c8 / c16 = zzzfuse's F gens blocks (same
#   method; 191.95 tok/s, full-row 33.62 ms / 237.0, 51.42 ms), its 1u = zzzc16's F reads (90.77 tok/s). KVR_ARMS="K0:19456 K35:16800 .."
#   adds a K0 start (~10 min) if the coordinator wants one.
# PER START (each arm): zzzc16's start (ngshare, no ATTACH, MAXSEQS 16, RADIANCE_DS41_RFUSE=2) with --host-pool-mib HP; every zzzc16 start
#   guard (modes, drafter, read-back, A11 / A4 / XPUSH lines, FUSE-R declare, swnote posts THE int16 PIN, rankrb every switch + the 4 ranks,
#   exl3_x3d 2, pin16 engagement, warm-up answers vs stock); then
#   0 PLACEMENT READ-BACK (kvsum.py place, from the start log + /stats right after the pin): --host-pool-mib in force (= HP), the VRAM split
#     (experts / kv cache / prefill staging), owned slab slots a rank (slab - shadow), KV- / arena- / drafter-lendable slots, the KV pool in
#     tokens + the engine's "S sessions at 524288" + sessions x 128k / 260k / 500k, deltas vs zzzc16's start; the knob not in force or the
#     split not moved = VIRHE -> NO reading for that start;
#   1 IDENTITY (strict, T 0 greedy, placement only so IDENTICAL is required): the warm-up answers vs stock, a1-F (greedy set c1 alone) vs
#     ref12's a1 AND vs zzzc16's a1-F -- ANY difference: VIRHE and THAT START's speed reads STOP (the next start still runs);
#   2 c8 WORK-BASED gens window (harness ncmb3 --window gens --gens 2: 16 newcomer steps), KVR_C8B 2 blocks under THE int16 PIN;
#   3 c16 gens (--gens 1), KVR_C16B 1 block;
#   4 1u essay (resprobe essay 512, T 0): ONE discarded read + KVR_U1N 3 back to back (ESSAY RESIDENCY WARM-UP + REF12 lesson);
#   every block's /stats window (ncmb3's samples + st-w0 / st-w1): VRAM units a rank, owned / KV-lent / arena-lent / drafter-slab-lent,
#   misses + hits by slot class, stream MB a step; the engine log (docker logs -t, RADIANCE_LOG_STEPS=1) captured at the start's end.
# SUMMARY (kvres/kvsum.py; lines "KVRES ..."): REFERENCES, PLACE / IDENTITY per arm, c8 BLOCK / c8 (agg + the full-row step p50 vs int16 F
#   191.95 / 33.62, window units vs K0), c16 BLOCK / c16 (vs 237.0 / 51.42), 1u (vs 90.77), one line an arm (units Δ, c8 / c16 / 1u %, KV
#   capacity: tokens, sessions at 524288, sessions x 500k / 260k / 128k, Δ vs K0), TABLE, SLOPE (c8 full-row ms per +100 resident units a rank
#   vs vramsweep's -2.0; n/a when the window units move < 20); ncmatch.py's matched newcomer sums + steps.py listings (INFO, zzzfuse's method).
# ~22 min for two starts (the first ~11.5 incl. the n-gram fill, the second ~9.5) + ~1 summary; BUDGET KVR_BUDGET_MIN 42 (a start begins only
#   if elapsed + KVR_STARTEST 11 fit; a section past it is skipped, logged). NO evict, no P0, no cc_sim, no build, no power / host / fan
#   settings; production compose files read only; nothing profiled. At the end the raw snapshots go into one tar.gz, the logs are gzipped,
#   the n-gram tables cleaned.
# MOCK: KVR_SW=0 = a server without the int9b .. int16 switches (queue-ar/tools/mockrad; kvres/mockrun-kvres.sh): the fusion switches and
#   exl3_x3d are not posted there, and the mock serves a real start log (host pool 19456), so the placement / identity checks are INFO.
#   DRYRUN=1 bash dsm-kvres.sh : prints every command; checks the image literals, the K25U plugin md5, every helper (+ selftests), the tables'
#   and steps.py's md5s, the ngramshare files, the sidecars, the yamls, the references (zzzc16 start log + a1-F, zzzfuse raw snapshots), the
#   disk; no server, no GPU.
set -u
HD="$(cd "$(dirname "$0")" && pwd)"
for LIB29 in "$HOME/gpu/ds41/exl3-test/queue-29/lib-29.sh" "$HD/../../../queue-29/lib-29.sh"; do [ -e "$LIB29" ] && break; done
[ -e "$LIB29" ] && . "$LIB29" || { echo "lib-29.sh not found"; exit 1; }
QA=$HOME/gpu/ds41/exl3-test/queue-ar
Y=$HD/../ds41-stack2-tp4.yaml                   # stack2's yaml, read only (env_file ${XS2_ENVFILE}; RADIANCE_AQL_STAMP from AQLSTAMP)
TL=$QA/tools
[ -e $TL/heatsoak.sh ] && . $TL/heatsoak.sh
O=${KVR_OUT:-$R/xdsm/kvres}; export STATSDIR=$O/stats
RD=$R/xdsm/draft; RM=$R/xdsm; RS5=$R/xdsm/stack5
export IMAGE=${KVR_IMAGE:?set KVR_IMAGE}
ITEM=${KVR_ITEM:-57-p4zyzzzzz-ds-r92zzzzzz-ref12zzzzzzzzzzzz-zsoak16zz-kvres}
PSKK=8; BIC=3; NOA=2; OCC=6; OCCK=32; DSA=0; HBR=0; HBRANKS=1,2      # stack5's S5T values, draft_sample 0 (the ARC screen's base)
SW=${KVR_SW:-1}
PLAN=""; PLAN2=""; PLAN3=""   # no lever groups: the reference reads (refreads)
F4V=${KVR_F4:-0}; F4G=${KVR_F4G:-0}; MXC=${KVR_MXCONFIRM:-0}; NTOK=${KVR_NTOK:-64}; DEPTHS=${KVR_DEPTHS:-}; GSC=${KVR_GSCONC:-16}
I11DIR=${KVR_I11DIR:-$R/xdsm/i11u}; I11ID=${KVR_I11ID:-$R/xdsm/i11u/x1u-a-O.jsonl}; R12S=$HD/../prof12/p12win.py; YDS=$HD/kvsum.py; SAS=$HD/kvsum.py; STP=$HD/../zzzc16/steps.py; NCM=$HD/../zzzc16/ncmatch.py; NCT=$HD/../ync/nctab.py; C48N=$HD/../cap48/ncmb.py; C48REF=${KVR_C48REF:-300.7}; C16DUR=${KVR_C16DUR:-30}; C16WARM=${KVR_C16WARM:-10}; NREADS=${KVR_NREADS:-3}
CBHK=${KVR_CBHK:-2}; EPR=${KVR_EPROMPTS:-essay,code}
MXV=${KVR_MX:-12}; EGEN=${KVR_EGEN:-512}; ARCV=0; DOID=0; STAMPN=0
MHC=${KVR_MHC:-1}; D0=${KVR_D0:-3}; CAP=${KVR_CAP:-48}; SPN=0; SPK=0
DOD=${KVR_D:-1}
P0=""   # no lever P0 (p0sel); A11's own P0 on one card (by chip UUID): p0nc
# lever A11's P0 (the byte check, then the bench -> nctab.py's ranged entries) and its in-range identity; A11ON 0 drops arms G / N
A11CMS=${KVR_A11CMS:-1000,1104,1105,1216,1408,1535,1536,1537}; A11MS=${KVR_A11MS:-1024,1104,1216,1408}; A11IT=${KVR_A11IT:-30}
A11RANGE=${KVR_A11_RANGE:-1000-1536}; A11MIN=${KVR_A11_MIN_PCT:-1.0}; A11ID=${KVR_A11ID-1100 1300}; P0PERFS=${KVR_P0PERFS:-600}; P0CHECKS=${KVR_P0CHECKS:-600}
A11ON=1; A11ENT=""; GATEWHY=""; IDBAD=""   # IDBAD: arms whose strict identity failed (never "best")
LDCONC=${KVR_LDCONC:-4}; LDPF=${KVR_LDPF:-8192}; STAGN=${KVR_STAGN:-1}; STAGB=${KVR_STAGB:-0}   # the staggered-arrival identity (zepb's epbstag): streams, fresh prefill tokens
CDEPTHS=${KVR_CDEPTHS-64000 136000}; NTOK=${KVR_NTOK:-64}
PFOK=0; A10=0; PDEPTHS=""   # (yd2m's lever A10: not in this item)
XPON=1; A4ON=1; IDFAIL=""; STOPPED=0   # int14c: a lever whose P0 fails is dropped (XPON / A4ON / A11ON 0); IDFAIL = the failed strict identities (THE STOP)
SWLON=${KVR_SWL:-1}; SWLG=${KVR_SWLG:-75}; SWLREADS=${KVR_SWLREADS:-1}   # SWL in Z + its reads (coordinator 12.11. after yswl: L1G075 = place_swap_lent 1 + heat_min_gain_x100 75)
C8ORD1=${KVR_C8ORDER1-BAGB}; C8ORD2=${KVR_C8ORDER2-BZZB}; U1N=${KVR_U1N:-3}; ALLEST=${KVR_ALLEST:-9}   # step 2 c8, step 3 c8, 1u reads an arm, step 3 minutes (kept when the SWL reads are weighed)
A4TAB=$HD/../zzzc16/m16-forms.txt; A4MD5=${KVR_A4MD5:-d55ad354}; A4N=${KVR_A4N:-95}; REF12A1=${KVR_REF12A1:-$R/xdsm/ref12/xref12-a1.jsonl}   # A4's table = yd2m's P0 bench (not re-benched); ref12's a1
NGS=$HOME/gpu/ds41/exl3-test/queue-ar/tools/ngramshare; NGB=0; NGCLEAN=0; NGDIR=${NGSHARE_DIR:-/dev/shm/ds41ng}   # n-gram reuse (TESTING.md BODY RULE)
