A11TAB=$HD/../zzzc16/a11-entries.txt; A11MD5=${KVR_A11MD5:-8e4fc84e}; A11NE=${KVR_A11NE:-8}   # A11's ranged entries = yzint14c's P0 (runs/xdsm/yzint14c/x1/p0-tab.entries), copied, NOT re-benched
C8GN=${KVR_C8GN:-2}; C8GORD=${KVR_C8GORDER-BZZB}; C8N=${KVR_C8N:-2}; C16N=${KVR_C16N:-2}; C4N=${KVR_C4N:-2}; C1N=${KVR_C1N:-1}; C4WARMUP=${KVR_C4WARMUP:-1}; SWN=${KVR_SWN:-2}   # the reading counts
ESSMD5=${KVR_ESSAY_MD5:-47a39dac581a}; CODEMD5=${KVR_CODE_MD5:-c5e7c82e3e11}   # yzint14c's resprobe answers (text_md5; every arm, every read)
# zzzc16: THE int16 confirmation's arms and readings (module header)
XB=${KVR_XB:-2}; XREF=${KVR_XREFUSE:-5}   # THE int15 PIN's exl3_x3d (2: X3D + K2.5 gate_up G3 + down U4) in every arm; XREF: swnote's refusal probe (400)
