U1AB=${KVR_U1ABBA-B F F B}; C4AB=${KVR_C4ABBA-B F F B}; C4GN=${KVR_C4GN:-3}; C4WA=${KVR_C4WARMARM:-F}; C16GN=${KVR_C16GN:-1}   # 1u ABBA blocks; c4 gens blocks (+ C4WARMUP's discarded one)
ONEU=${KVR_1U:-1}; C4ON=${KVR_C4:-1}; COLD=${KVR_COLD:-1}; CDEP=${KVR_CDEPTH:-136000}; COLDEST=${KVR_COLDEST:-2}; POSTN=${KVR_POST:-10}   # sections on / off; the cold depth and its budget estimate
IDARMS=F; GSA=F; LDA=F   # identity runs under F (THE int16 PIN) only
