C8B=${KVR_C8B:-2}; C16B=${KVR_C16B:-1}; U1ON=${KVR_1U:-1}; STARTEST=${KVR_STARTEST:-11}; STARTN=0; KVSTOPS=""; KVDONE=""   # c8 / c16 gens blocks a start, 1u on, minutes a start
REFHP=19456; REFZC=${KVR_REFZC:-$R/xdsm/zzzc16}; REFZF=${KVR_REFZF:-$R/xdsm/zzzfuse}   # the K0 references: zzzc16 (int16 start: placement, a1-F, 1u F), zzzfuse (c8 / c16 F gens blocks)
REFSTART=${KVR_REFSTART:-$REFZC/start-xzc16-n5.log.gz}; ZCA1=${KVR_ZCA1:-$REFZC/xzc16-a1-F.jsonl}
for v in $C8B $C16B $U1ON $STARTEST; do case $v in ''|*[!0-9]*) echo "a kvres knob is not a number ('$v')"; exit 1 ;; esac; done
[ -n "$KVARMS" ] || { echo "KVR_ARMS names no arm"; exit 1; }
for e in $KVARMS; do
  case $e in [A-Za-z]*:[0-9]*) ;; *) echo "KVR_ARMS entries are NAME:HOSTPOOL_MIB (got '$e')"; exit 1 ;; esac
  case ${e%%:*} in *[!A-Za-z0-9]*) echo "KVR_ARMS: an arm name is letters / digits (got '${e%%:*}')"; exit 1 ;; esac
  case ${e#*:} in *[!0-9]*) echo "KVR_ARMS: the host pool is MiB (got '${e#*:}')"; exit 1 ;; esac
  [ ${e#*:} -ge 12288 ] && [ ${e#*:} -le 24576 ] || { echo "KVR_ARMS: --host-pool-mib 12288 .. 24576 (below ~13000 the KV pool nears one 524288-token sequence + the staging ring) (got ${e#*:})"; exit 1; }
done
[ "$(echo $KVARMS | tr ' ' '\n' | cut -d: -f1 | sort | uniq -d)" = "" ] || { echo "KVR_ARMS: an arm name twice"; exit 1; }
[ $C8B -ge 1 ] && [ $C16B -le 4 ] && [ $C8B -le 4 ] || { echo "KVR_C8B 1..4, KVR_C16B 0..4"; exit 1; }
case $U1ON in 0|1) ;; *) echo "KVR_1U 0 or 1"; exit 1 ;; esac
STPMD5=${KVR_STPMD5:-569fd59b}   # the coordinator's steps.py (zzzc16/steps.py = zzzfuse's = zzk25s's)
REFZF=${KVR_REFZF:-$R/xdsm/zzzfuse}; ZFA1=${KVR_ZFA1:-$REFZF/xzfuse-a1-B.jsonl}   # zzzfuse's run: its a1-B (int15, IDENTICAL to ref12's a1 there) -- a1-F here must equal it
R14C=${KVR_R14COLD:-$R/xdsm/ref14/cold-136000-1-O.txt}; R14CMD5=${KVR_R14CMD5:-3623688c}; ZFC=${KVR_ZFCOLD:-$REFZF/cold-136000-1-F.txt}   # the 136k answers byte-compared: ref14's (md5 3623688c = ref12's); zzzfuse's only if it exists (it ran none)
for v in $XB $XREF $RFDECL $C4GN $C16GN $ONEU $C4ON $COLD $CDEP $COLDEST $POSTN; do case $v in ''|*[!0-9]*) echo "a zzzc16 knob is not a number ('$v')"; exit 1 ;; esac; done
[ $XB = 2 ] || { echo "KVR_XB 2 (THE int15 PIN's exl3_x3d)"; exit 1; }; [ $RFDECL = 2 ] || { echo "KVR_RFDECL 2 (int16 declares FUSE-R and starts at form 2)"; exit 1; }
[ $XREF -ge 5 ] || { echo "KVR_XREFUSE >= 5 (0 .. 4 are VALID on the K25U plugin: a probe there SETS the switch)"; exit 1; }
[ $C4GN -ge 1 ] || { echo "KVR_C4GN >= 1"; exit 1; }; case $ONEU$C4ON$COLD in [01][01][01]) ;; *) echo "KVR_1U / KVR_C4 / KVR_COLD 0 or 1"; exit 1 ;; esac
[ -n "$U1AB" ] && [ -n "$C4AB" ] || { echo "KVR_U1ABBA / KVR_C4ABBA must name blocks"; exit 1; }
for a in $U1AB $C4AB $C4WA; do case $a in B|F) ;; *) echo "KVR_U1ABBA / C4ABBA / C4WARMARM take B (int15) and F (int16) (got '$a')"; exit 1 ;; esac; done
case " $U1AB " in *" B "*) ;; *) echo "KVR_U1ABBA needs B (the reading is F vs B)"; exit 1 ;; esac; case " $U1AB " in *" F "*) ;; *) echo "KVR_U1ABBA needs F"; exit 1 ;; esac
for v in $C8GN $C8N $C16N $C4N $C1N $SWN; do case $v in ''|*[!0-9]*) echo "a ref14 count knob is not a number ('$v')"; exit 1 ;; esac; done
case $C4WARMUP in 0|1) ;; *) echo "KVR_C4WARMUP 0 or 1"; exit 1 ;; esac; [ $C8GN -ge 1 ] || { echo "KVR_C8GN >= 1"; exit 1; }
case $C8GORD in *[!BZ]*) echo "KVR_C8GORDER takes B (every int14 lever at 0 = int12 bytes) and Z (the int14 pin) (got '$C8GORD')"; exit 1 ;; esac
XPMIN=${KVR_XPMIN:-1048576}; XPROWS=${KVR_XPROWS:-48,256,1024}   # XPUSH's bound (coordinator 13.11., FN 5f0352a8; RADIANCE_FN4_AR_XPUSH_MIN at start) and the P0 gate check's rows x 5120
case $XPMIN in ''|*[!0-9]*) echo "KVR_XPMIN is an element count"; exit 1 ;; esac; case $XPROWS in *[!0-9,]*|'') echo "KVR_XPROWS rows, comma separated"; exit 1 ;; esac
[ -n "$(echo $XPROWS | tr ',' '\n' | awk -v m=$XPMIN '$1 * 5120 >= m' | head -1)" ] && [ -n "$(echo $XPROWS | tr ',' '\n' | awk -v m=$XPMIN '$1 * 5120 < m' | head -1)" ] || { echo "KVR_XPROWS needs a size below and one above KVR_XPMIN (x 5120)"; exit 1; }
case $SWLON$SWLREADS in [01][01]) ;; *) echo "KVR_SWL / KVR_SWLREADS take 0 or 1"; exit 1 ;; esac
for v in $SWLG $U1N $ALLEST $A4N; do case $v in ''|*[!0-9]*) echo "a knob is not a number ('$v')"; exit 1 ;; esac; done
