case $C8ORD1 in *[!BAG]*|'') echo "KVR_C8ORDER1 takes B, A (A9) and G (A11) (got '$C8ORD1')"; exit 1 ;; esac
case $C8ORD2 in *[!BZ]*|'') echo "KVR_C8ORDER2 takes B and Z (ALL) (got '$C8ORD2')"; exit 1 ;; esac
case $A11CMS$A11MS in *[!0-9,]*|'') echo "KVR_A11CMS / KVR_A11MS rows, comma separated"; exit 1 ;; esac
