for o in "$CORD" "$U1ORD"; do case $o in *[!BAGN]*) echo "KVR_U1ORDER takes B A G N (got '$o')"; exit 1 ;; esac; done
case $C16ORD in *[!BAGNX]*) echo "KVR_C16ORDER takes B A G N and X (= the best arm by c8) (got '$C16ORD')"; exit 1 ;; esac
case $C8ORD in *[!BAGN]*|'') echo "KVR_C8ORDER takes B, A (A9), G (A11) and N (both) (got '$C8ORD')"; exit 1 ;; esac
case $DECTH in ''|*[!0-9.]*) echo "KVR_DECTH is a percentage (got '$DECTH')"; exit 1 ;; esac
