MT=192; SEED=1234
case $SW in 0|1) ;; *) echo "KVR_SW is 1 (the item) or 0 (a server without the int9b / int10 / int11 switches: the mock) (got '$SW')"; exit 1 ;; esac
for v in $MXV $EGEN $ARCV $DOID $STAMPN $MHC $D0 $CAP $DOD $DISKMIN $BUDGET $CBHK ${KVR_C8WIN:-35} ${KVR_C8WARM:-10} ${KVR_C4WIN:-35} ${KVR_C4WARM:-8} ${KVR_C1WIN:-35} ${KVR_C1WARM:-6} ${KVR_CSPACING:-6} ${KVR_C8X:-0} ${KVR_C4ID:-0} ${KVR_C8GENS:-0}; do case $v in ''|*[!0-9]*) echo "a numeric knob is not a number ('$v')"; exit 1 ;; esac; done
case $MXV in 0|12|16|24) ;; *) echo "KVR_MX 0 / 12 / 16 / 24 (ds41_mix_wv's values)"; exit 1 ;; esac
case $F4V in ''|*[!0-9]*) echo "KVR_F4 0 / 1 / 2..64 (ds41_shexp_lane)"; exit 1 ;; esac; [ $F4V -le 64 ] || { echo "KVR_F4 0..64"; exit 1; }
[ $F4V -le 1 ] || [ $F4G = 1 ] || { echo "KVR_F4 $F4V (a row threshold) needs the F4G image: set KVR_F4G=1 (its literal is then checked)"; exit 1; }
for v in $F4G $MXC $NTOK $GSC; do case $v in ''|*[!0-9]*) echo "a numeric knob is not a number ('$v')"; exit 1 ;; esac; done
