if pl and all(x == 0 for x in pl) and ps and all(x == ws for x in ps) and mg and all(x == wm for x in mg) and hy and all(x == 125 for x in hy): sys.exit(0)
print(("VIRHE" if sw else "INFO (KVR_SW=0)") + " the arm %s on the ranks (/stats): place_swl %s (want %d), heat_min_gain_x100 %s (want %d), heat_hyst_x100 %s (want 125), place_lf %s (want 0)" % (
