  # libr4d reads the table at its first rule call (a prefill launch above 48 rows), not at load: one ~300-token prompt first if no line yet
  docker logs $CN 2>&1 | grep -q 'lever GPF form table from RADIANCE_DS41_GG_PF_TABLE' || { curl -s -m 120 -X POST -H 'Content-Type: application/json' -d "{\"prompt\": \"$(printf 'The quick brown fox jumps over the lazy dog near the river bank. %.0s' $(seq 1 25))\", \"n_predict\": 1, \"temperature\": 0}" $URL/completion > /dev/null 2>&1; sleep 1; }
