             # 125, place_lf 0 (SWL lives in each rank's mover) -> 0; else VIRHE -> 1 (not read) (KVR_SW=0: INFO, 0)
  [ "$DRY" = 1 ] && { echo "+ RESULT xkvr $1: THE int16 PIN read back -- GET /admin/fn4 ds41_rfuse $FRF, ds41_mix_fin $FMF, route_copy_ov $FRC, exl3_x3d $XB, ds41_bi 6, gg_pf 2, ar_xpush 1, gg_gemv_m16 1, place_swap_lent 1, heat_min_gain_x100 $SWLG, heat_hyst_x100 125 (+ every other switch of the pin), nothing pending; GET /stats on each of the 4 ranks place_swl 1, heat_min_gain_x100 $SWLG, heat_hyst_x100 125, place_lf 0 (else VIRHE: not read)"; return 0; }
