    if mv[k]: bad.append("%s +%s (want 0)" % (k, mv[k]))
txt = "GET /admin/fn4 ds41_rfuse/ds41_mix_fin/route_copy_ov/exl3_x3d %s, rco in_force %s, fuse rf_declared %s rf_layers %s | over the probe (arm O, epoch_bump, + 64 tok): %s" % (
    "/".join(str(x) for x in sw), rb.get("in_force"), fb.get("rf_declared"), fb.get("rf_layers"), ", ".join("%s +%s" % kv for kv in mv.items()))
print(("OK " if not bad else "") + txt + ("" if not bad else " -- " + "; ".join(bad)))' $O/fn-$1-eng-0.json $O/fn-$1-eng-1.json $FRF $FMF $FRC $XB 2>&1 | head -1 | cut -c1-1500)
  case "$r" in OK*) xlog "$1 THE int16 PIN read back + engagement: ${r#OK }"; return 0 ;; esac
  [ $SW = 0 ] && { xlog "$1 THE int16 PIN engagement: INFO (KVR_SW=0 mock: no fusion switches / counters served) $r"; return 0; }
  xlog "$1 THE int16 PIN read back + engagement: VIRHE $r -- nothing is read"; return 1
}
c16id() {   # 1 THE IDENTITY BLOCK (strict, T 0 greedy; module header) under F = THE int16 PIN: the warm-up answers vs stock (identw at the start);
            # a1-F vs ref12's a1 AND vs zzzfuse's a1-B (int15); gs16-F vs a1-F; STRICT staggered ld-F vs a1-F -- every check runs (each failure
            # named), then c16reads stops on IDFAIL
  local g u0 u1
  idok n5   # the warm-up answers vs stock (no line = not compared = the stop)
  stopfile && return 0
  alone xkvr F a1-F
  if [ -s "$REF12A1" ] || [ "$DRY" = 1 ]; then cmpx xkvr a1-F-vs-ref12-a1 $REF12A1 $O/xkvr-a1-F.jsonl; idok a1-F-vs-ref12-a1
  else xlog "identity a1-F vs ref12 a1: VIRHE $REF12A1 missing -- not compared"; IDFAIL="$IDFAIL a1-F-vs-ref12-a1(reference-missing)"; fi
  if [ -s "$ZFA1" ] || [ "$DRY" = 1 ]; then cmpx xkvr a1-F-vs-zzzfuse-a1-B $ZFA1 $O/xkvr-a1-F.jsonl; idok a1-F-vs-zzzfuse-a1-B
  else xlog "identity a1-F vs zzzfuse a1-B: VIRHE $ZFA1 missing -- not compared"; IDFAIL="$IDFAIL a1-F-vs-zzzfuse-a1-B(reference-missing)"; fi
  stopfile && return 0
  u0=$(utcnow); ssnap xkvr-gs$GSC-F-0; gsx F; ssnap xkvr-gs$GSC-F-1; u1=$(utcnow)
  [ "$DRY" = 1 ] || echo "$u0 $u1" > $O/gs$GSC-F.win
  g=$(gt48 xkvr-gs$GSC-F)
  xlog "gs$GSC-F cap (MAXSEQS ${MAXSEQS:-?}, all $GSC in flight, sched_row_cap $CAP): $(capd xkvr-gs$GSC-F-0 xkvr-gs$GSC-F-1) | steps_gt48 delta ${g:-na}$([ "${g:-na}" = 0 ] || { [ $SW = 1 ] && echo " -- VIRHE > 48-row steps under the cap (or no cap counters)" || echo " -- INFO (SW=0 mock: no cap counters)"; }) | fuse counters over gs16: $(fusectr xkvr-gs$GSC-F-0 xkvr-gs$GSC-F-1)"
  cmpx xkvr gs$GSC-F-vs-a1-F $O/xkvr-a1-F.jsonl $O/xkvr-gs$GSC-F.jsonl; idok gs$GSC-F-vs-a1-F
  stopfile && return 0
  stagx F F || true
  fusesay "identity"
  return 0
}
fusectr() {   # fusectr A B -> one line: GET /admin/fn4 "fuse" / "rco" counter deltas between the snapshots fn-A.json and fn-B.json (engagement: a recorded pass counts at recording)
  [ "$DRY" = 1 ] && { echo "(dry: fuse / rco deltas)"; return 0; }
  python3 -c 'import json,sys
def g(p, o):
    try: return (json.load(open(p)).get(o) or {})
    except (OSError, ValueError): return {}
a, b = g(sys.argv[1], "fuse"), g(sys.argv[2], "fuse")
ra, rb = g(sys.argv[1], "rco"), g(sys.argv[2], "rco")
k = ("rf_form1_passes", "rf_form2_passes", "rgs_launches", "mixfin_launches", "mixfin_rows")
print("declared %s, layers %s | " % (b.get("rf_declared"), b.get("rf_layers")) + ", ".join("%s +%s" % (x, (b.get(x) or 0) - (a.get(x) or 0)) for x in k)
      + " | rco in_force %s, " % rb.get("in_force") + ", ".join("%s +%s" % (x, (rb.get(x) or 0) - (ra.get(x) or 0)) for x in ("recordings", "copies", "freed")))' $O/fn-$1.json $O/fn-$2.json 2>/dev/null || echo "fuse counters n/a"
}
coldid() {   # coldid: the cold CDEP answer (F) byte for byte vs ref14's (R14C, md5 R14CMD5 = ref12's) and zzzfuse's (ZFC, only if that run made one)
             # -> identity.txt; a difference = VIRHE (reported; nothing follows it, so no stop)
  local f=$O/cold-$CDEP-1-F.txt r m
  if [ "$DRY" = 1 ]; then echo "+ cmpfile $R14C $f (ref14's $CDEP answer, md5 $R14CMD5 $([ -s $R14C ] && echo present || echo MISSING)) + cmpfile $ZFC $f ($([ -s $ZFC ] && echo present || echo "absent: zzzfuse ran no $CDEP -> not compared")) -> identity.txt (DIFFERENT = VIRHE)"; return 0; fi
  [ -s $f ] || { xlog "cold $CDEP answer: VIRHE no answer text $f -- not compared"; return 0; }
  m=$(md5sum < $R14C 2>/dev/null | cut -c1-8)
  [ "$m" = "$R14CMD5" ] || xlog "cold $CDEP: NOTE ref14's answer $R14C is md5 ${m:-?}, not $R14CMD5"
  r=$(cmpfile $R14C $f); idrec xkvr-cold$CDEP-F-vs-ref14 "$r" "$(basename $R14C) vs $(basename $f), deepq $CDEP, $NTOK greedy tokens"
  case "$r" in IDENTICAL*) ;; *) xlog "cold $CDEP F vs ref14: $([ $SW = 1 ] && echo VIRHE || echo "INFO (KVR_SW=0 mock: the mock's text is not a real answer)") the answer differs ($r; F md5 $(md5sum < $f | cut -c1-8), ref14 ${m:-?})" ;; esac
  if [ -s $ZFC ]; then r=$(cmpfile $ZFC $f); idrec xkvr-cold$CDEP-F-vs-zzzfuse "$r" "$(basename $ZFC) vs $(basename $f)"
    case "$r" in IDENTICAL*) ;; *) xlog "cold $CDEP F vs zzzfuse: $([ $SW = 1 ] && echo VIRHE || echo "INFO (KVR_SW=0 mock)") the answer differs ($r)" ;; esac
  else xlog "cold $CDEP F vs zzzfuse: not compared (zzzfuse ran no $CDEP read: $ZFC absent; ref14's is the reference)"; fi
}
c16reads() {   # the readings in their order (module header): 1 identity under F (THE STOP on any failure), 2 1u ABBA, 3 c4 gens (one discarded +
               # B F F B), 4 the optional cold 136k (F; the first section the budget drops)
  local i a k
  if budok "identity (warm-up, a1-F vs ref12 a1 + zzzfuse a1-B, gs$GSC-F, staggered ld-F)" 4; then c16id || true
  else IDFAIL="$IDFAIL budget"; xlog "identity SKIPPED by the budget: VIRHE"; fi
  stopfile && return 0
  if [ -n "$IDFAIL" ]; then
    STOPPED=1
    xlog "IDENTITY GATE: VIRHE strict identity failed [$(echo $IDFAIL)] -> the item STOPS before every speed block (exact = byte-identical: NEEDS USER) | arm F $(armj F) on THE int16 PIN | the failing comparisons are in $O/identity.txt and $O/xkvr-*-cmp-*.json"
    return 0
  fi
  xlog "IDENTITY GATE: every strict check IDENTICAL ($([ "$DRY" = 1 ] && echo "dry: no" || grep -c IDENTICAL $O/identity.txt 2>/dev/null) lines) -> the speed blocks run | B $(armj B) | F $(armj F)"
  # 2 1u ABBA (ESSAY RESIDENCY WARM-UP + REF12 lesson: the same prompt back to back): each block = one discarded warm-up read + U1N reads
  if [ $ONEU = 1 ]; then
    SETK=0
    for a in $U1AB; do SETK=$((SETK + 1)); SETN=U1-$SETK; stopfile && return 0
      budok "1u block $SETK $a (1 discarded + $U1N essay reads back to back)" 1 || continue
      blockx U1W $a essay || true
      for k in $(seq 1 $U1N); do stopfile && return 0; blockx U1 $a essay || true; done
    done
    SETN=""; SETK=0
    fusesay "1u ABBA [$U1AB]"
  else xlog "1u ABBA: OFF (KVR_1U=0)"; fi
  # 3 c4 WORK-BASED (WINDOW QUANTUM): one DISCARDED warm-up block, then C4AB (B F F B), gens C4GN each
  if [ $C4ON = 1 ]; then
    xlog "c4: harness/ncmb3.py --window gens --gens $C4GN ($((4 * C4GN)) newcomer steps a block), the fixed prompt set reset per block, T 0 | $([ $C4WARMUP = 1 ] && echo "one DISCARDED warm-up block (arm $C4WA), then " || echo "no warm-up block (KVR_C4WARMUP=0), ")[$C4AB]"
    if [ $C4WARMUP = 1 ] && budok "c4 warm-up (one DISCARDED gens block, arm $C4WA)" 2; then mbx 4 w1 $C4WA G w$C4WA || true; fi
    i=0; for a in $C4AB; do i=$((i + 1)); stopfile && return 0
      budok "c4 gens block $i $a (gens $C4GN)" 2 || continue
      mbx 4 $i $a G || true
    done
    fusesay "c4 [$C4AB]"
  else xlog "c4: OFF (KVR_C4=0)"; fi
  # 4 cold CDEP under F (optional; the first section dropped)
  if [ $COLD = 1 ]; then
    stopfile && return 0
    if budok "cold $CDEP (deepq after a prefix-cache reset, F; the first section the budget drops)" $COLDEST; then coldx $CDEP F 1 || true; coldid; fi
  else xlog "cold $CDEP: OFF (KVR_COLD=0)"; fi
  return 0
}
c16summary() {   # zc16sum.py (every INT16 line: identity, the pin read-back, 1u ABBA, c4 gens, 136k), then the raw snapshots into one tar.gz and the logs gzipped
  local EL=$O/xkvr-n5-engine-full.log.gz l
  if [ "$DRY" = 1 ]; then
    echo "+ python3 -I -B $SAS $O --log $EL --sw $SW --tag xkvr-n5 --post $POSTN --want 'B=0/0/0,F=$FRF/$FMF/$FRC' --xb $XB --swlg $SWLG --rfdecl $RFDECL --u1n $U1N --c4gens $C4GN --essay-md5 $ESSMD5 --cold-depth $CDEP --cold-ref-md5 $R14CMD5 --stopped <0|1> --json $O/zc16sum.json > $O/zc16sum.txt -> RESULT xkvr INT16 lines (PIN / IDENTITY / 1u BLOCK / 1u ARM / 1u F vs B / 1u VERDICT / c4 BLOCK / c4 F vs B / c4 INFO / 136k / SUMMARY)"
    echo "+ tar -czf $O/raw-snaps.tar.gz (st-*.json fn-*.json m-*.txt c8/*-samp.jsonl c8/*-st-w*.json) and remove them; gzip the start log, the ld text, the 1u / mb / cold texts"
    return 0
  fi
  [ $STOPPED = 1 ] && xlog "summary: STOPPED at the identity gate -- no speed block ran (the INT16 lines give the identity and the pin read-back)"
  [ -s $EL ] || xlog "summary: NOTE no engine log $EL (the start did not come up): no step-log readings"
  timeout 300 python3 -I -B $SAS $O --log $EL --sw $SW --tag xkvr-n5 --post $POSTN --want "B=0/0/0,F=$FRF/$FMF/$FRC" --xb $XB --swlg $SWLG --rfdecl $RFDECL --u1n $U1N --c4gens $C4GN --essay-md5 $ESSMD5 --cold-depth $CDEP --cold-ref-md5 $R14CMD5 --stopped $STOPPED --json $O/zc16sum.json > $O/zc16sum.txt 2>&1
  while IFS= read -r l; do xlog "${l:0:2600}"; done < <(grep -h '^INT16' $O/zc16sum.txt 2>/dev/null)
  grep -q '^INT16' $O/zc16sum.txt 2>/dev/null || xlog "summary: VIRHE zc16sum.py printed no INT16 line ($(tail -3 $O/zc16sum.txt 2>/dev/null | tr '\n' ' ' | cut -c1-300))"
  grep -q '^Traceback' $O/zc16sum.txt 2>/dev/null && xlog "summary: VIRHE a Traceback in zc16sum.py ($(grep -A4 '^Traceback' $O/zc16sum.txt | tail -2 | tr '\n' ' ' | cut -c1-300))"
  ( cd $O && tar -czf raw-snaps.tar.gz $(ls st-*.json fn-*.json m-*.txt c8/*-samp.jsonl c8/*-st-w*.json 2>/dev/null) 2>/dev/null \
      && rm -f st-*.json fn-*.json m-*.txt c8/*-samp.jsonl c8/*-st-w*.json ) || xlog "summary: NOTE the raw snapshots were not archived (left as they are)"
  gzip -f $O/start-*.log $O/xkvr-ld-*.txt $O/c8/*.txt $O/b*-U1*.txt $O/cold-*.out 2>/dev/null || true
  xlog "summary: raw snapshots -> raw-snaps.tar.gz ($(du -m $O/raw-snaps.tar.gz 2>/dev/null | cut -f1) MB); logs gzipped; $O $(du -sm $O 2>/dev/null | cut -f1) MB; $(dfree) MB free on /"
  return 0
}
ngclean() {   # the end (or an early exit): ngram-shm-cleanup.sh (keeper stop + the tables and .lock files removed: FN items follow), logged (yswl's)
  local r b
  NGCLEAN=1
  run "docker rm -f $CN > /dev/null 2>&1"
  if [ "$DRY" = 1 ]; then echo "+ $NGS/ngram-shm-cleanup.sh   (keeper stop + $NGDIR/ngram-*.tab + .lock removed; refuses beside a radiance container; logs to runs/queue-changes.log) -- now: $(DRYRUN=1 $NGS/ngram-shm-cleanup.sh 2>&1 | tail -3 | tr '\n' ' ' | cut -c1-300)"; return 0; fi
  b=$(df -B1 --output=used /dev/shm 2>/dev/null | tail -1 | awk '{printf "%.1f GiB", $1 / 1073741824}')
  r=$("$NGS/ngram-shm-cleanup.sh" 2>&1 | tail -3 | tr '\n' ' ' | cut -c1-600)
  case "$r" in *REFUSED*) xlog "ngshare cleanup: VIRHE $r -- the tables stay in $NGDIR (run ngram-shm-cleanup.sh before the FN items)" ;;
    *) xlog "ngshare cleanup: $r | /dev/shm used $b -> $(df -B1 --output=used /dev/shm 2>/dev/null | tail -1 | awk '{printf "%.1f GiB", $1 / 1073741824}') | left in $NGDIR: $(ls $NGDIR 2>/dev/null | tr '\n' ' ' | cut -c1-200)" ;; esac
}
fusestart() {   # fusestart TAG: the int16 start state of the fusion levers -- the FUSE-R declare line "now RFDECL" with form 2 beside every trunk router
                # (> 0 layers), GET /admin/fn4 ds41_rfuse RFDECL / ds41_mix_fin 0 / route_copy_ov 0 (RCO and FUSE-M come by fn4 only), "fuse".rf_declared
                # and "rco" present, RADIANCE_DS41_MIX_FIN / RADIANCE_AQL_ROUTE_OV NOT in the container env, the refusals ds41_rfuse 3 / ds41_mix_fin 2 /
                # route_copy_ov 2 -> 400 -> 0; anything else: VIRHE -> 1 (nothing read; int16 needs form 2)
  local ln g r3 m2 c2 nf1 nf2 ce ev
  if [ "$DRY" = 1 ]; then
    echo "+ fusestart $1: the start log's 'lever FUSE-R (ds41_rfuse, RADIANCE_DS41_RFUSE, now $RFDECL) declared: beside the router of N MoE layers -- router_scored_topk_scatter (form 1 ..) at N1, router_gemm_f32_scored_topk_scatter (form 2 ..) at N2' (now $RFDECL, N2 > 0, else VIRHE); GET /admin/fn4 ds41_rfuse $RFDECL, ds41_mix_fin 0, route_copy_ov 0, \"fuse\".rf_declared > 0, \"rco\" present; RADIANCE_DS41_MIX_FIN / RADIANCE_AQL_ROUTE_OV not in the env; POST ds41_rfuse 3 / ds41_mix_fin 2 / route_copy_ov 2 -> 400"
    return 0
  fi
  ln=$(docker logs $CN 2>&1 | grep -m1 'lever FUSE-R (ds41_rfuse' | sed 's/^radiance: //; s/^[A-Z]\[[0-9]\] //; s/^[A-Z] *//' | cut -c1-400)
  g=$(fn4get | python3 -c 'import json,sys; d=json.load(sys.stdin); w=d.get("switches") or {}; f=d.get("fuse") or {}; print(w.get("ds41_rfuse"), w.get("ds41_mix_fin"), w.get("route_copy_ov"), f.get("rf_declared"), f.get("rf_layers"), "rco" if isinstance(d.get("rco"), dict) else "no-rco")' 2>/dev/null)
  ce=$(docker inspect -f '{{range .Config.Env}}{{println .}}{{end}}' $CN 2>/dev/null); ev=$(echo "$ce" | grep -c '^RADIANCE_DS41_MIX_FIN=\|^RADIANCE_AQL_ROUTE_OV=')
  r3=400; m2=400; c2=400   # the refusal probes: not under KVR_SW=0 (the mock knows none of these switches)
  [ $SW = 1 ] && { r3=$(fn4code '{"ds41_rfuse": 3}'); m2=$(fn4code '{"ds41_mix_fin": 2}'); c2=$(fn4code '{"route_copy_ov": 2}'); }
  read -r nf1 nf2 < <(echo "$ln" | python3 -c 'import re,sys
m = re.search(r"form 1, [^)]*\) at (\d+), .*form 2, [^)]*\) at (\d+)", sys.stdin.read())
print(m.group(1), m.group(2)) if m else print(-1, -1)' 2>/dev/null || echo "-1 -1")
  xlog "$1 levers FUSE-R / FUSE-M / RCO at start (RADIANCE_DS41_RFUSE=$RFDECL declared): '${ln:-NO FUSE-R line}' | GET ds41_rfuse / ds41_mix_fin / route_copy_ov / fuse.rf_declared / rf_layers / rco ${g:-none} | env RADIANCE_DS41_MIX_FIN / RADIANCE_AQL_ROUTE_OV $ev (want 0) | refusals ds41_rfuse 3 -> HTTP $r3, ds41_mix_fin 2 -> HTTP $m2, route_copy_ov 2 -> HTTP $c2"
  if [ $SW = 0 ]; then xlog "$1 levers FUSE-R / FUSE-M / RCO: INFO (KVR_SW=0 mock: not served) -- the mock's arms all run the int8 pin"; return 0; fi
  case "$ln" in *"now $RFDECL)"*) ;; *) xlog "$1: VIRHE the FUSE-R declare line does not say 'now $RFDECL' ('${ln:-none}'): RADIANCE_DS41_RFUSE=$RFDECL did not take"; return 1 ;; esac
  [ "${nf2:--1}" -gt 0 ] 2>/dev/null || { xlog "$1: VIRHE FUSE-R form 2 not declared ($nf2 layers): int16 cannot run"; return 1; }
  case "$g" in "$RFDECL 0 0 "*" rco") ;; *) xlog "$1: VIRHE GET /admin/fn4 ds41_rfuse / ds41_mix_fin / route_copy_ov '${g:-none}' at start (want $RFDECL 0 0, \"rco\" present)"; return 1 ;; esac
  case "$g" in "$RFDECL 0 0 0 "*|"$RFDECL 0 0 None "*) xlog "$1: VIRHE GET /admin/fn4 fuse.rf_declared '${g:-none}' (want > 0)"; return 1 ;; esac
  [ "$ev" = 0 ] || { xlog "$1: VIRHE RADIANCE_DS41_MIX_FIN / RADIANCE_AQL_ROUTE_OV in the container env ($ev): int16 sets them by fn4 only"; return 1; }
  [ "$r3" = 400 ] && [ "$m2" = 400 ] && [ "$c2" = 400 ] || { xlog "$1: VIRHE a fusion refusal probe was not refused (ds41_rfuse 3 -> $r3, ds41_mix_fin 2 -> $m2, route_copy_ov 2 -> $c2)"; return 1; }
  return 0
}
ncmset() {   # ncmset LOG LABEL MIN REQS...: ncmatch.py over the blocks (NAME = REQS minus -reqs.jsonl, ARM = its last field) -> ncm-LABEL.json / .txt (zzzfuse's)
  local el=$1 lb=$2 mn=$3 f nm bl="" l; shift 3
  for f in "$@"; do [ -s "$f" ] || continue; nm=$(basename $f -reqs.jsonl); bl="$bl --block $nm:${nm##*-}:$f"; done
  [ -n "$bl" ] || return 0
  timeout 300 python3 -I -B $NCM $el --set $lb $bl --min $mn --json $O/ncm-$lb.json > $O/ncm-$lb.txt 2>&1
  while IFS= read -r l; do xlog "${l:0:1600}"; done < <(grep -h '^NCMATCH' $O/ncm-$lb.txt 2>/dev/null)
  grep -q '^Traceback' $O/ncm-$lb.txt 2>/dev/null && xlog "summary: VIRHE ncmatch.py $lb: $(grep -A4 '^Traceback' $O/ncm-$lb.txt | tail -2 | tr '\n' ' ' | cut -c1-300)"
  return 0
}
stepsx() {   # stepsx PLAIN REQS: the coordinator's steps.py (zzzc16/steps.py = zzzfuse's, md5 STPMD5) over one gens block: every non-decode step and every
             # step with a prefill segment in [w0 - 2 s, w1 + 2 s] with its wall and in-window flag -> c8/NAME-steps.txt; logs its in-window non-decode walls (INFO; zzzfuse's)
  local nm w t0 t1 w0 w1
  nm=$(basename $2 -reqs.jsonl); w=$(mwin $2)
  [ -n "$w" ] || return 0
  read -r t0 t1 w0 w1 < <(python3 -c 'import sys
from datetime import datetime, timezone
a, b = float(sys.argv[1]), float(sys.argv[2])
iso = lambda t: datetime.fromtimestamp(t, timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")
print(iso(a - 2.0), iso(b + 2.0), iso(a), iso(b))' ${w%%:*} ${w#*:})
  timeout 120 python3 -I -B $STP $1 $t0 $t1 $w0 $w1 > $O/c8/$nm-steps.txt 2>&1
  xlog "$nm steps.py (raw, INFO): $(awk '$NF == "True" && $3 != "decode" { n++; if ($(NF-1) != "None") s += $(NF-1) } END { printf "%d in-window non-decode step(s), walls %.1f ms", n, s }' $O/c8/$nm-steps.txt 2>/dev/null)$(grep -q '^Traceback' $O/c8/$nm-steps.txt 2>/dev/null && echo " -- VIRHE steps.py: $(tail -1 $O/c8/$nm-steps.txt | cut -c1-200)")"
}
kvprep() {   # kvprep: ONCE before the first start -- int14's tables (zzzc16's = ref14's, NOT re-benched) and zzzc16's start words (LEVENV + A4's
             # table, XPUSH's bound, FUSE-R declared at RFDECL, A11's ranged entries in the GPF table) -> 0, else VIRHE -> 1 (no start)
