  echo "+ docker ps: $(docker ps --format '{{.Names}}' | grep -iE '^radiance' | tr '\n' ' ')(information here; the real run refuses to start beside one)"
  echo "+ disk now: $(dfree) MB free on / (guard $DISKMIN MB)"
fi
mkd $O $O/guard $O/c8 $O/snap $STATSDIR
[ "$DRY" = 1 ] || : > $O/identity.txt
if ! stopfile; then
  . $NGS/ngshare.sh || { xlog "VIRHE ngshare.sh did not load (Y $Y) -- not started"; exit 1; }
  NGB=1
  xlog "ngshare.sh sourced -- Y $(basename $Y), restart() wrapped (keeper prep before, keeper start --wait 120 --expect 2 after); n-gram tables before the start: $(ls $NGDIR/ngram-*.tab 2>/dev/null | wc -l) ($([ "$(ls $NGDIR/ngram-*.tab 2>/dev/null | wc -l)" -gt 0 ] && echo "reused if the probes match" || echo "this start fills them, ~308 s"))"
  if kvprep; then
    for e in $KVARMS; do
      stopfile && break
      budok "start ${e%%:*} (--host-pool-mib ${e#*:})" $STARTEST || continue
      kvstart ${e%%:*} ${e#*:} || true
    done
  fi
  xlog "starts: read [$(echo $KVDONE)] | stopped / no reading [$(echo $KVSTOPS)] | $(elapsed) min"
fi
kvsummary
unset $SWITCHES
down
[ $NGB = 1 ] && ngclean
xlog "$ITEM: done ($(elapsed) min) -- $O | $([ -n "$(echo $KVSTOPS)" ] && echo "arms with NO reading or a STOP: $(echo $KVSTOPS) (see the VIRHE lines) | ")$([ $NV = 0 ] && echo "no VIRHE line" || echo "$NV VIRHE line(s): see above")"
